-- Nahraď `PROJECT.DATASET` svým GCP projektem a datasetem.

CREATE TABLE IF NOT EXISTS `collectorboycz.MarketingData.fb_page_daily` (
  date DATE NOT NULL OPTIONS (description = 'Den, ke kterému se denní metriky vztahují. Odvozeno jako end_time minus jeden den.'),
  page_id STRING NOT NULL OPTIONS (description = 'ID Facebook stránky.'),
  followers_count INT64 OPTIONS (description = 'Celkový počet sledujících na konci dne podle page_follows; stavová hodnota, nesčítat přes dny.'),
  page_media_view INT64 OPTIONS (description = 'Celkový počet zobrazení obsahu stránky během dne; opakovaná zobrazení se započítávají.'),
  page_total_media_view_unique INT64 OPTIONS (description = 'Počet jedinečných lidí, kterým se obsah stránky během dne zobrazil (denní dosah).'),
  page_post_engagements INT64 OPTIONS (description = 'Počet interakcí s příspěvky stránky během dne podle definice Meta.'),
  page_total_actions INT64 OPTIONS (description = 'Celkový počet akcí provedených na stránce během dne podle definice Meta.'),
  page_views_total INT64 OPTIONS (description = 'Celkový počet zobrazení stránky během dne.'),
  page_video_views INT64 OPTIONS (description = 'Počet zhlédnutí videí stránky během dne podle definice Meta.'),
  page_daily_follows INT64 OPTIONS (description = 'Počet nových sledování stránky za den podle metriky Meta.'),
  page_daily_follows_unique INT64 OPTIONS (description = 'Počet jedinečných lidí, kteří stránku začali sledovat během dne.'),
  page_daily_unfollows_unique INT64 OPTIONS (description = 'Počet jedinečných lidí, kteří stránku přestali sledovat během dne.'),
  page_lifetime_engaged_followers_unique INT64 OPTIONS (description = 'Počet jedinečných sledujících, kteří interagovali se stránkou; ukládá se denní hodnota vrácená API.'),
  page_actions_post_reactions_like_total INT64 OPTIONS (description = 'Počet reakcí Like na příspěvky během dne.'),
  page_actions_post_reactions_love_total INT64 OPTIONS (description = 'Počet reakcí Love na příspěvky během dne.'),
  page_actions_post_reactions_wow_total INT64 OPTIONS (description = 'Počet reakcí Wow na příspěvky během dne.'),
  page_actions_post_reactions_haha_total INT64 OPTIONS (description = 'Počet reakcí Haha na příspěvky během dne.'),
  page_actions_post_reactions_sorry_total INT64 OPTIONS (description = 'Počet reakcí Sorry na příspěvky během dne.'),
  page_actions_post_reactions_anger_total INT64 OPTIONS (description = 'Počet reakcí Anger na příspěvky během dne.'),
  page_actions_post_reactions_total JSON OPTIONS (description = 'Rozpad denních reakcí na příspěvky podle typu; API vrací objekt JSON, nikoli jedno číslo.'),
  page_video_views_organic INT64 OPTIONS (description = 'Počet organických zhlédnutí videí stránky během dne.'),
  page_video_views_paid INT64 OPTIONS (description = 'Počet placených zhlédnutí videí stránky během dne.'),
  page_video_view_time INT64 OPTIONS (description = 'Celkový čas sledování videí stránky za den v jednotce vrácené Meta API.'),
  page_video_repeat_views INT64 OPTIONS (description = 'Počet opakovaných zhlédnutí videí stránky během dne.'),
  page_video_complete_views_30s INT64 OPTIONS (description = 'Počet zhlédnutí videí alespoň 30 sekund (nebo celého videa, je-li kratší) během dne.'),
  page_video_complete_views_30s_unique INT64 OPTIONS (description = 'Počet jedinečných lidí, kteří během dne zhlédli video alespoň 30 sekund (nebo celé kratší video).'),
  page_video_complete_views_30s_organic INT64 OPTIONS (description = 'Počet organických zhlédnutí videí alespoň 30 sekund během dne.'),
  page_video_complete_views_30s_paid INT64 OPTIONS (description = 'Počet placených zhlédnutí videí alespoň 30 sekund během dne.'),
  page_video_complete_views_30s_autoplayed INT64 OPTIONS (description = 'Počet automaticky spuštěných zhlédnutí videí alespoň 30 sekund během dne.'),
  page_video_complete_views_30s_click_to_play INT64 OPTIONS (description = 'Počet zhlédnutí videí alespoň 30 sekund po kliknutí na přehrávání během dne.'),
  page_video_complete_views_30s_repeat_views INT64 OPTIONS (description = 'Počet opakovaných zhlédnutí videí alespoň 30 sekund během dne.'),
  page_video_views_autoplayed INT64 OPTIONS (description = 'Počet zhlédnutí videí spuštěných automaticky během dne.'),
  page_video_views_click_to_play INT64 OPTIONS (description = 'Počet zhlédnutí videí spuštěných kliknutím na přehrávání během dne.'),
  page_video_views_by_paid_non_paid JSON OPTIONS (description = 'Rozpad denních zhlédnutí videí podle placené a neplacené distribuce, ve struktuře vrácené Meta API.'),
  page_video_views_by_uploaded_hosted JSON OPTIONS (description = 'Rozpad denních zhlédnutí podle typu videa/hostingu, ve struktuře vrácené Meta API.'),
  ingested_at TIMESTAMP NOT NULL OPTIONS (description = 'Čas, kdy byl řádek načten do BigQuery.')
)
PARTITION BY date
CLUSTER BY page_id;

